def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(x for row in g for x in row), key=lambda c: sum(row.count(c) for row in g))
    seen = set()

    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            y0 = min(y for y, x in cells); y1 = max(y for y, x in cells)
            x0 = min(x for y, x in cells); x1 = max(x for y, x in cells)
            # Fill the interior of rectangular outlines; odd-sized outlines use 7, even use 2.
            if y1 - y0 >= 2 and x1 - x0 >= 2:
                border = all(g[y][x] == color for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
                             if y in (y0, y1) or x in (x0, x1))
                if border:
                    fill = 7 if (y1 - y0 + 1) % 2 else 2
                    for y in range(y0 + 1, y1):
                        for x in range(x0 + 1, x1):
                            if g[y][x] == bg or g[y][x] == color:
                                g[y][x] = fill
    return g
